  "safety.share_sub": { en: "Send family a map link to where you are", hi: "परिवार को अपनी जगह का नक्शा-लिंक भेजें", gu: "પરિવારને તમારી જગ્યાની નકશા-લિંક મોકલો", ta: "குடும்பத்துக்கு நீங்கள் இருக்கும் இடத்தின் வரைபட இணைப்பை அனுப்புங்கள்", bn: "পরিবারকে আপনার জায়গার মানচিত্র-লিংক পাঠান" },
  "safety.tips": { en: "GOOD TO KNOW", hi: "जानने लायक", gu: "જાણવા જેવું", ta: "தெரிந்துகொள்ள வேண்டியவை", bn: "জেনে রাখুন" },
  "safety.tip1": { en: "112 works even without a SIM card or balance.", hi: "112 बिना सिम या बैलेंस के भी काम करता है।", gu: "112 સિમ કે બેલેન્સ વગર પણ ચાલે છે.", ta: "சிம் கார்டு அல்லது இருப்பு இல்லாமலும் 112 வேலை செய்யும்.", bn: "সিম বা ব্যালান্স ছাড়াও 112 কাজ করে।" },
  "safety.tip2": { en: "At stations and airports, take a prepaid taxi or an app cab. Check the number plate before you get in.", hi: "स्टेशन और एयरपोर्ट पर प्रीपेड टैक्सी या ऐप कैब लें, बैठने से पहले नंबर प्लेट जाँचें।", gu: "સ્ટેશન અને એરપોર્ટ પર પ્રીપેડ ટેક્સી કે એપ કેબ લો, બેસતાં પહેલાં નંબર પ્લેટ તપાસો.", ta: "நிலையங்கள், விமான நிலையங்களில் ப்ரீபெய்ட் டாக்ஸி அல்லது ஆப் கேப் பயன்படுத்துங்கள்; ஏறும் முன் எண் பலகையைச் சரிபாருங்கள்.", bn: "স্টেশন ও বিমানবন্দরে প্রিপেড ট্যাক্সি বা অ্যাপ ক্যাব নিন, ওঠার আগে নম্বর প্লেট দেখে নিন।" },
  "safety.tip3": { en: "At big festivals, choose a place to meet in case someone gets lost.", hi: "भीड़ वाले त्योहारों में अंदर जाने से पहले बच्चों और बड़ों के साथ मिलने की जगह तय करें।", gu: "ભીડવાળા તહેવારોમાં અંદર જતાં પહેલાં બાળકો અને વડીલો સાથે મળવાની જગ્યા નક્કી કરો.", ta: "கூட்டமான திருவிழாக்களில், உள்ளே போகும் முன் குழந்தைகள், பெரியவர்களுடன் சந்திக்கும் இடத்தை முடிவு செய்யுங்கள்.", bn: "ভিড়ের উৎসবে ঢোকার আগে বাচ্চা ও বয়স্কদের সঙ্গে দেখা করার জায়গা ঠিক করে নিন।" },

