  "lg.welcome": { en: "Welcome back", hi: "फिर से स्वागत है", gu: "ફરી સ્વાગત છે", ta: "மீண்டும் வருக", bn: "আবার স্বাগত" },
  "lg.create_sub": { en: "It takes less than a minute.", hi: "एक मिनट से भी कम लगता है।", gu: "એક મિનિટથી પણ ઓછો સમય લાગે છે.", ta: "ஒரு நிமிடத்துக்கும் குறைவாகவே ஆகும்.", bn: "এক মিনিটেরও কম লাগে।" },
  "lg.welcome_sub": { en: "Log in to continue.", hi: "आगे बढ़ने के लिए लॉग इन करें।", gu: "આગળ વધવા લૉગ ઇન કરો.", ta: "தொடர உள்நுழையுங்கள்.", bn: "চালিয়ে যেতে লগ ইন করুন।" },
