  "lg.pw_hint": { en: "At least 8 characters.", hi: "कम से कम 8 अक्षर।", gu: "ઓછામાં ઓછા 8 અક્ષર.", ta: "குறைந்தது 8 எழுத்துகள்.", bn: "অন্তত 8টি অক্ষর।" },
