  "tk.title": { en: "Tickets & bookings", hi: "टिकट और बुकिंग", gu: "ટિકિટ અને બુકિંગ", ta: "டிக்கெட் & முன்பதிவுகள்", bn: "টিকিট ও বুকিং" },
