  "sv.no_match": { en: "No matches", hi: "कुछ नहीं मिला", gu: "કંઈ ન મળ્યું", ta: "பொருத்தம் இல்லை", bn: "কিছু মেলেনি" },
  "sv.no_offline": { en: "Nothing offline yet", hi: "अभी ऑफ़लाइन कुछ नहीं", gu: "હજી ઑફલાઇન કંઈ નથી", ta: "இன்னும் ஆஃப்லைனில் எதுவும் இல்லை", bn: "এখনও অফলাইনে কিছু নেই" },
  "sv.none_tab": { en: "Nothing saved here yet", hi: "यहाँ अभी कुछ सहेजा नहीं", gu: "અહીં હજી કંઈ સાચવ્યું નથી", ta: "இங்கே இன்னும் எதுவும் சேமிக்கவில்லை", bn: "এখানে এখনও কিছু রাখা নেই" },
  "sv.no_match_sub": { en: "Nothing saved matches “{q}”.", hi: "“{q}” से मेल खाता कुछ सहेजा नहीं है।", gu: "“{q}” સાથે મળતું કંઈ સાચવ્યું નથી.", ta: "“{q}” உடன் பொருந்தும் எதுவும் சேமிக்கவில்லை.", bn: "“{q}”-এর সঙ্গে মেলে এমন কিছু রাখা নেই।" },
  "sv.offline_sub": { en: "Download the Ahmedabad pack to keep your saved things for when there's no signal.", hi: "नेटवर्क न होने पर भी सहेजी चीज़ों के लिए अहमदाबाद पैक डाउनलोड करें।", gu: "નેટવર્ક ન હોય ત્યારે પણ સાચવેલું જોવા અમદાવાદ પૅક ડાઉનલોડ કરો.", ta: "சிக்னல் இல்லாதபோதும் சேமித்தவற்றைப் பார்க்க அகமதாபாத் தொகுப்பைப் பதிவிறக்குங்கள்.", bn: "নেটওয়ার্ক না থাকলেও রাখা জিনিস দেখতে আহমেদাবাদ প্যাক ডাউনলোড করুন।" },
  "sv.plans_sub": { en: "Tell the AI where you're going and who's coming, and it plans each day. Your plan will wait for you here.", hi: "AI को बताइए कहाँ जा रहे हैं और कौन साथ है, वह हर दिन की योजना बनाएगा। आपकी योजना यहाँ मिलेगी।", gu: "AI ને કહો ક્યાં જાઓ છો અને કોણ સાથે છે, તે દરરોજનું આયોજન કરશે. તમારું આયોજન અહીં મળશે.", ta: "எங்கே போகிறீர்கள், யார் வருகிறார்கள் என்று AI-யிடம் சொல்லுங்கள், அது ஒவ்வொரு நாளையும் திட்டமிடும். உங்கள் திட்டம் இங்கே இருக்கும்.", bn: "AI-কে বলুন কোথায় যাচ্ছেন আর কে সঙ্গে, সে প্রতিদিন সাজাবে। আপনার পরিকল্পনা এখানে থাকবে।" },
  "sv.empty_sub": { en: "Tap the bookmark on any place, walk or story and it will wait for you here.", hi: "किसी भी जगह, सैर या कहानी पर बुकमार्क दबाएँ, वह यहाँ मिलेगी।", gu: "કોઈ પણ જગ્યા, ચાલ કે વાર્તા પર બુકમાર્ક દબાવો, તે અહીં મળશે.", ta: "எந்த இடம், நடை அல்லது கதையிலும் புக்மார்க்கைத் தட்டுங்கள், அது இங்கே இருக்கும்.", bn: "যেকোনো জায়গা, হাঁটা বা গল্পে বুকমার্ক চাপুন, সেটা এখানে থাকবে।" },
  "sv.plan_trip": { en: "Plan a trip", hi: "यात्रा बनाएँ", gu: "યાત્રા બનાવો", ta: "பயணம் திட்டமிடு", bn: "ভ্রমণ সাজান" },
  "sv.explore": { en: "Explore nearby", hi: "आसपास घूमें", gu: "આસપાસ ફરો", ta: "அருகில் ஆராயுங்கள்", bn: "কাছাকাছি ঘুরে দেখুন" },
  "sv.pack_body": { en: "42 places, 30 stories, 2 walks and the Old City map. Updated 2 days ago.", hi: "42 जगहें, 30 कहानियाँ, 2 सैर और पुराने शहर का नक्शा। 2 दिन पहले अपडेट हुआ।", gu: "42 જગ્યાઓ, 30 વાર્તાઓ, 2 ચાલ અને જૂના શહેરનો નકશો. 2 દિવસ પહેલાં અપડેટ થયું.", ta: "42 இடங்கள், 30 கதைகள், 2 நடைகள், பழைய நகர வரைபடம். 2 நாட்களுக்கு முன் புதுப்பிக்கப்பட்டது.", bn: "42টি জায়গা, 30টি গল্প, 2টি হাঁটা আর পুরনো শহরের মানচিত্র। 2 দিন আগে আপডেট হয়েছে।" },
  "sv.up_to_date": { en: "Ahmedabad pack is up to date", hi: "अहमदाबाद पैक नया है", gu: "અમદાવાદ પૅક અપડેટ છે", ta: "அகமதாபாத் தொகுப்பு புதியது", bn: "আহমেদাবাদ প্যাক আপডেটেড" },
  "sv.checking": { en: "Checking for updates…", hi: "अपडेट देख रहे हैं…", gu: "અપડેટ તપાસીએ છીએ…", ta: "புதுப்பிப்புகளைச் சரிபார்க்கிறோம்…", bn: "আপডেট দেখা হচ্ছে…" },
