  "ct.gujarat": { en: "Gujarat · walks, stories and the map", hi: "गुजरात · सैर, कहानियाँ और नक्शा", gu: "ગુજરાત · ચાલ, વાર્તાઓ અને નકશો", ta: "குஜராத் · நடைகள், கதைகள், வரைபடம்", bn: "গুজরাট · হাঁটা, গল্প আর মানচিত্র" },
  "geo.none": { en: "This browser can't share location. You can still pick a city.", hi: "यह ब्राउज़र लोकेशन नहीं दे सकता। आप शहर चुन सकते हैं।", gu: "આ બ્રાઉઝર લોકેશન આપી શકતું નથી. તમે શહેર પસંદ કરી શકો.", ta: "இந்த உலாவியால் இருப்பிடம் தர முடியாது. நீங்கள் நகரத்தைத் தேர்ந்தெடுக்கலாம்.", bn: "এই ব্রাউজার লোকেশন দিতে পারে না। আপনি শহর বাছতে পারেন।" },
  "geo.on": { en: "Location on. You're in {city}", hi: "लोकेशन चालू। आप {city} में हैं", gu: "લોકેશન ચાલુ. તમે {city}માં છો", ta: "இருப்பிடம் இயக்கத்தில். நீங்கள் {city} இல்", bn: "লোকেশন চালু। আপনি {city}-তে" },
  "geo.near": { en: "Location on. The nearest city Virasa knows is {city}, {km} km away", hi: "लोकेशन चालू। विरासा का सबसे पास का शहर {city} है, {km} km दूर", gu: "લોકેશન ચાલુ. વિરાસાનું સૌથી નજીકનું શહેર {city} છે, {km} km દૂર", ta: "இருப்பிடம் இயக்கத்தில். விராசாவுக்குத் தெரிந்த அருகிலுள்ள நகரம் {city}, {km} km தொலைவில்", bn: "লোকেশন চালু। বিরাসার জানা সবচেয়ে কাছের শহর {city}, {km} km দূরে" },
  "geo.off": { en: "No location for now. You can turn it on later.", hi: "अभी लोकेशन नहीं। बाद में चालू कर सकते हैं।", gu: "હમણાં લોકેશન નહીં. પછી ચાલુ કરી શકો.", ta: "இப்போதைக்கு இருப்பிடம் இல்லை. பின்னர் இயக்கலாம்.", bn: "এখন লোকেশন নেই। পরে চালু করতে পারেন।" },
  "geo.finding": { en: "Finding you…", hi: "आपको ढूँढ रहे हैं…", gu: "તમને શોધીએ છીએ…", ta: "உங்களைக் கண்டுபிடிக்கிறோம்…", bn: "আপনাকে খোঁজা হচ্ছে…" },
  "dc.tabs": { en: "What to discover", hi: "क्या खोजें", gu: "શું શોધવું", ta: "எதைக் கண்டறிய", bn: "কী খুঁজবেন" },
