  "dc.ask": { en: "Explain {name}, {city} to me: why locals love it, its story, and how to enjoy a visit.", hi: "{city} के {name} के बारे में बताओ: लोग इसे क्यों पसंद करते हैं, इसकी कहानी, और घूमने का अच्छा तरीका।", gu: "{city}ના {name} વિશે કહો: લોકો કેમ ગમાડે છે, તેની વાર્તા અને મુલાકાતની સારી રીત.", ta: "{city} இல் உள்ள {name} பற்றிச் சொல்: உள்ளூர் மக்கள் ஏன் விரும்புகிறார்கள், அதன் கதை, எப்படிச் சுற்றிப் பார்ப்பது.", bn: "{city}-র {name} নিয়ে বলো: স্থানীয়রা কেন ভালোবাসে, এর গল্প, আর ভালোভাবে ঘোরার উপায়।" },
  "pn.removed": { en: "Plan removed from Saved", hi: "योजना सहेजे से हटाई", gu: "આયોજન સાચવેલામાંથી કાઢ્યું", ta: "திட்டம் சேமித்தவையிலிருந்து நீக்கப்பட்டது", bn: "পরিকল্পনা সংরক্ষিত থেকে সরানো হয়েছে" },
  "pn.title": { en: "Plan your trip", hi: "अपनी यात्रा बनाएँ", gu: "તમારી યાત્રા બનાવો", ta: "உங்கள் பயணத்தைத் திட்டமிடு", bn: "আপনার ভ্রমণ সাজান" },
