  "pn.book": { en: "Book entry tickets", hi: "प्रवेश टिकट बुक करें", gu: "પ્રવેશ ટિકિટ બુક કરો", ta: "நுழைவுச் சீட்டுகளைப் பதிவு செய்", bn: "প্রবেশ টিকিট বুক করুন" },
  "pn.book_sub": { en: "Book now, pay there", hi: "अभी बुक करें, वहाँ पैसे दें", gu: "હમણાં બુક કરો, ત્યાં પૈસા આપો", ta: "இப்போது பதிவு, அங்கே பணம்", bn: "এখন বুক করুন, সেখানে টাকা দিন" },
