  "pn.pack_sub": { en: "Stories and maps without signal", hi: "बिना नेटवर्क कहानियाँ और नक्शे", gu: "નેટવર્ક વગર વાર્તાઓ અને નકશા", ta: "சிக்னல் இல்லாமல் கதைகள், வரைபடங்கள்", bn: "নেটওয়ার্ক ছাড়া গল্প আর মানচিত্র" },
  "pn.ask": { en: "I have {days} in {city}. What else should I know before I go?", hi: "मेरे पास {city} में {days} हैं। जाने से पहले और क्या जानना चाहिए?", gu: "મારી પાસે {city}માં {days} છે. જતાં પહેલાં બીજું શું જાણવું જોઈએ?", ta: "எனக்கு {city} இல் {days} உள்ளன. போவதற்கு முன் வேறு என்ன தெரிந்துகொள்ள வேண்டும்?", bn: "আমার {city}-তে {days} আছে। যাওয়ার আগে আর কী জানা দরকার?" },
  "pn.ask_city": { en: "Ask the guide about {city}", hi: "{city} के बारे में गाइड से पूछें", gu: "{city} વિશે ગાઈડને પૂછો", ta: "{city} பற்றி வழிகாட்டியிடம் கேளுங்கள்", bn: "{city} নিয়ে গাইডকে জিজ্ঞেস করুন" },
  "pn.ask_city_sub": { en: "Tap any stop above to ask about it", hi: "किसी पड़ाव के बारे में पूछने के लिए ऊपर टैप करें", gu: "કોઈ સ્ટોપ વિશે પૂછવા ઉપર ટૅપ કરો", ta: "எந்த நிறுத்தம் பற்றியும் கேட்க மேலே தட்டுங்கள்", bn: "কোনো স্টপ নিয়ে জানতে ওপরে চাপুন" },
  "pn.view": { en: "View in Saved", hi: "सहेजे में देखें", gu: "સાચવેલામાં જુઓ", ta: "சேமித்தவையில் பார்", bn: "সংরক্ষিত-এ দেখুন" },
