  "ar.finish": { en: "Finish tour", hi: "टूर पूरा करें", gu: "ટૂર પૂરી કરો", ta: "சுற்றுலாவை முடி", bn: "ট্যুর শেষ করুন" },
  "ar.next": { en: "Next stop · {name}", hi: "अगला पड़ाव · {name}", gu: "આગળનો સ્ટોપ · {name}", ta: "அடுத்த நிறுத்தம் · {name}", bn: "পরের স্টপ · {name}" },
  "ar.complete": { en: "Tour complete", hi: "टूर पूरा हुआ", gu: "ટૂર પૂરી થઈ", ta: "சுற்றுலா முடிந்தது", bn: "ট্যুর শেষ" },
  "ar.back_map": { en: "Back to the map", hi: "नक्शे पर वापस", gu: "નકશા પર પાછા", ta: "வரைபடத்துக்குத் திரும்பு", bn: "মানচিত্রে ফিরুন" },
  "ar.restart": { en: "Start again", hi: "फिर से शुरू करें", gu: "ફરી શરૂ કરો", ta: "மீண்டும் தொடங்கு", bn: "আবার শুরু করুন" },
  "ar.h1": { en: "Hold up your phone", hi: "फ़ोन ऊपर उठाएँ", gu: "ફોન ઊંચો કરો", ta: "ஃபோனை உயர்த்திப் பிடியுங்கள்", bn: "ফোন তুলে ধরুন" },
  "ar.h1s": { en: "Point the camera at the building. The stop you are at is shown on screen.", hi: "कैमरा इमारत की ओर करें। आप जिस पड़ाव पर हैं वह स्क्रीन पर दिखेगा।", gu: "કૅમેરા ઇમારત તરફ રાખો. તમે જે સ્ટોપ પર છો તે સ્ક્રીન પર દેખાશે.", ta: "கேமராவைக் கட்டடத்தை நோக்கிக் காட்டுங்கள். நீங்கள் இருக்கும் நிறுத்தம் திரையில் தெரியும்.", bn: "ক্যামেরা বাড়ির দিকে ধরুন। আপনি যে স্টপে আছেন তা স্ক্রিনে দেখা যাবে।" },
  "ar.h2s": { en: "The story of each stop plays by itself. Pause it any time.", hi: "हर पड़ाव की कहानी अपने आप चलती है। कभी भी रोकें।", gu: "દરેક સ્ટોપની વાર્તા જાતે ચાલે છે. ક્યારેય પણ રોકો.", ta: "ஒவ்வொரு நிறுத்தத்தின் கதையும் தானாக இயங்கும். எப்போதும் நிறுத்தலாம்.", bn: "প্রতিটি স্টপের গল্প নিজে থেকেই চলে। যেকোনো সময় থামান।" },
  "ar.h3": { en: "Walk on", hi: "आगे चलें", gu: "આગળ ચાલો", ta: "தொடர்ந்து நடங்கள்", bn: "এগিয়ে চলুন" },
  "ar.h3s": { en: "When a stop is done it gets a tick. Tap Next stop and follow the arrows.", hi: "पड़ाव पूरा होने पर उस पर निशान लगता है। अगला पड़ाव दबाएँ और तीरों के पीछे चलें।", gu: "સ્ટોપ પૂરો થાય ત્યારે નિશાની આવે છે. આગળનો સ્ટોપ દબાવો અને તીર પાછળ ચાલો.", ta: "நிறுத்தம் முடிந்ததும் சரிக்குறி வரும். அடுத்த நிறுத்தம் தட்டி அம்புகளைப் பின்தொடருங்கள்.", bn: "স্টপ শেষ হলে টিক পড়ে। পরের স্টপ চেপে তীর ধরে চলুন।" },
  "ar.got": { en: "Got it", hi: "समझ गया", gu: "સમજાઈ ગયું", ta: "புரிந்தது", bn: "বুঝেছি" },
  "ar.stops": { en: "Tour stops", hi: "टूर के पड़ाव", gu: "ટૂરના સ્ટોપ", ta: "சுற்றுலா நிறுத்தங்கள்", bn: "ট্যুরের স্টপ" },
