  "at.title": { en: "The Tree of Life, then and now", hi: "ट्री ऑफ़ लाइफ़, तब और अब", gu: "ટ્રી ઓફ લાઇફ, ત્યારે અને હવે", ta: "வாழ்க்கை மரம், அன்றும் இன்றும்", bn: "জীবনবৃক্ষ, তখন আর এখন" },
