  "rl.saved_toast": { en: "Saved. Find it under Saved › Stories", hi: "सहेजा। ‘सहेजे › कहानियाँ’ में देखें", gu: "સાચવ્યું. ‘સાચવેલું › વાર્તાઓ’માં જુઓ", ta: "சேமிக்கப்பட்டது. ‘சேமித்தவை › கதைகள்’ இல் பாருங்கள்", bn: "রাখা হয়েছে। ‘সংরক্ষিত › গল্প’-এ দেখুন" },
  "rl.ask_aria": { en: "Ask the AI Guide about this reel", hi: "इस रील के बारे में AI गाइड से पूछें", gu: "આ રીલ વિશે AI ગાઈડને પૂછો", ta: "இந்த ரீல் பற்றி AI வழிகாட்டியிடம் கேளுங்கள்", bn: "এই রিল নিয়ে AI গাইডকে জিজ্ঞেস করুন" },
