  "rl.narrated": { en: "Told in English · {t}", hi: "अंग्रेज़ी में · {t}", gu: "અંગ્રેજીમાં · {t}", ta: "ஆங்கிலத்தில் · {t}", bn: "ইংরেজিতে · {t}" },
