export type Key = keyof typeof D;
// Lets a server-rendered screen hand a phrase key to a toast or button that translates it.
export const isKey = (k: string): k is Key => Object.prototype.hasOwnProperty.call(D, k);
type Vars = Record<string, string | number>;

const fill = (s: string, vars?: Vars) => (vars ? s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? "")) : s);
export const asLang = (id: string): Lang => (["en", "hi", "gu", "ta", "bn"].includes(id) ? (id as Lang) : "en");

export function translate(lang: string, key: Key, vars?: Vars) {
  const e: Entry = D[key];
  return fill(MORE[lang]?.[key] || e[asLang(lang)] || e.en, vars);
}

// In components: const t = useT(); t("home.title")
export function useT() {
  const [lang] = useStored("lang", "en");
  // Stable while the language stays the same, so screens can list it in effect dependencies.
  return useCallback((key: Key, vars?: Vars) => translate(lang, key, vars), [lang]);
}

// Outside React (toasts from event handlers).
export const tr = (key: Key, vars?: Vars) => translate(readStored("lang", "en"), key, vars);

// For server-rendered screens: <T k="home.title" />
export function T({ k, v }: { k: Key; v?: Vars }) {
  return <>{useT()(k, v)}</>;
}

// The speech voice for each language.
export const VOICE: Record<string, string> = { en: "en-IN", hi: "hi-IN", gu: "gu-IN", ta: "ta-IN", bn: "bn-IN", mr: "mr-IN", te: "te-IN", kn: "kn-IN", ml: "ml-IN", pa: "pa-IN" };
